import { condition, defineQuery, defineSignal, proxyActivities, setHandler } from '@temporalio/workflow';

const { notify, parkTicket } = proxyActivities({ startToCloseTimeout: '1 minute' });

export const decidePlan = defineSignal('decidePlan');
export const stop = defineSignal('stop');
export const status = defineQuery('status');

export async function ticketToPr(ticket) {
  let state = 'Awaiting approval';
  let decision;
  let stoppedBy;
  setHandler(decidePlan, (d) => {
    decision = d;
  });
  setHandler(stop, (by) => {
    stoppedBy = by;
  });
  setHandler(status, () => state);

  const answered = () => decision !== undefined || stoppedBy !== undefined;
  await notify(`The plan for ${ticket} is ready. Approve, Change or Stop?`);
  if (!(await condition(answered, '20 seconds'))) {
    await notify(`Reminder: the plan for ${ticket} is still waiting for you.`);
    if (!(await condition(answered, '40 seconds'))) {
      state = 'Parked';
      await parkTicket(ticket);
      return 'parked';
    }
  }
  if (stoppedBy) {
    state = 'Stopped';
    return `stopped by ${stoppedBy}`;
  }
  state = 'Working';
  return `${decision.kind} by ${decision.by}`;
}
